import java.util.*;

class Solution {
    public boolean isBipartite(int[][] graph) {
        int n = graph.length;
        int[] color = new int[n];
        Arrays.fill(color, -1);

        for (int start = 0; start < n; start++) {
            if (color[start] != -1) {
                continue;
            }
            Queue<Integer> queue = new ArrayDeque<>();
            color[start] = 0;
            queue.offer(start);

            while (!queue.isEmpty()) {
                int node = queue.poll();
                for (int neighbor : graph[node]) {
                    if (color[neighbor] == -1) {
                        color[neighbor] = 1 - color[node];
                        queue.offer(neighbor);
                    } else if (color[neighbor] == color[node]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public boolean isBipartite(int[][] graph) {
        int n = graph.length;
        int[] color = new int[n];
        Arrays.fill(color, -1);

        for (int node = 0; node < n; node++) {
            if (color[node] == -1 && !dfs(graph, color, node, 0)) {
                return false;
            }
        }
        return true;
    }

    private boolean dfs(int[][] graph, int[] color, int node, int expectedColor) {
        if (color[node] != -1) {
            return color[node] == expectedColor;
        }
        color[node] = expectedColor;
        for (int neighbor : graph[node]) {
            if (!dfs(graph, color, neighbor, 1 - expectedColor)) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public boolean isBipartite(int[][] graph) {
        UnionFind uf = new UnionFind(graph.length);
        for (int node = 0; node < graph.length; node++) {
            int[] neighbors = graph[node];
            for (int neighbor : neighbors) {
                if (uf.connected(node, neighbor)) {
                    return false;
                }
                uf.union(neighbors[0], neighbor);
            }
        }
        return true;
    }

    static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }
            if (size[rootA] < size[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        boolean connected(int a, int b) {
            return find(a) == find(b);
        }
    }
}

